import { useMemo, useState } from "react";
import type { PaperMap as MapData } from "../../api/types";
import { FocusGraph, type FGCard, type FGEdge } from "../../map/FocusGraph";

export function PaperMap({ map, onSelect }: { map: MapData; onSelect(at: string): void }) {
  const [history, setHistory] = useState<string[]>([]);
  const id = history.at(-1) ?? map.root;

  const cards = useMemo(() => {
    return new Map(Object.entries(map.nodes).map(([key, entry]): [string, FGCard] => {
      const topic = entry.topic ? map.topics[entry.topic] : undefined;
      return [key, {
        id: key, title: entry.title, kicker: ["Section", "Appendix"].includes(entry.kind) ? "" : entry.kind,
        role: "step",
        tone: topic ? `var(--tone-${topic.tone})` : undefined,
        topic: topic?.title,
        order: entry.order,
      }];
    }));
  }, [map]);
  const edges = useMemo(() => map.links.flatMap((link): FGEdge[] => {
    if (link.from !== id && link.to !== id) return [];
    if (link.kind === "contains") return [link];
    return [{ from: link.from, to: link.to, kind: link.kind,
      why: link.kind === "reported_in"
        ? `${map.nodes[link.to].kind} reports this comparison or result.`
        : `${map.nodes[link.from].title} refers to ${map.nodes[link.to].title}.`,
      href: link.evidence.url }];
  }), [id, map]);

  return (
    <FocusGraph
      context="paper"
      spread={id === map.root}
      embeddedHeader={{
        title: "Paper map",
        action: history.length > 0 && <button className="map-pane__layout-button" type="button" onClick={() => setHistory(history.slice(0, -1))}>Back</button>,
      }}
      subjects={[id]}
      card={(key) => cards.get(key)}
      edges={edges}
      onSubject={(key) => {
        if (key === map.root) setHistory([]);
        else if (key !== id) setHistory([...history, key]);
        const entry = map.nodes[key];
        if (entry.at) onSelect(entry.at);
      }}
      roles={{ step: { many: "Sections, figures and passages" } }}
    />
  );
}
